/* =============================================================
   Calculateur cellulose soufflée PROFIB CELL — Go Passif
   Fichier appelé via <div id="CC_calculateur"></div>
                      <script src=".../calculateur-cellulose-ProfibCell.js"></script>
   Ce fichier embarque le CSS et le HTML en base64.
   ============================================================= */

// ── URL de base ──
var CC_BASE;
(function(){
  var s=document.currentScript;
  var src=s?s.src:'';
  CC_BASE=src.replace(/[^/]*$/,'');
})();

// ── CSS / HTML embarqués (remplis lors de l'assemblage) ──
var CC_CSS_B64='';
var CC_HTML_B64='';

function CC_decodeB64(b64){
  return decodeURIComponent(escape(window.atob(b64)));
}

function CC_injectUI(cb){
  var mount=document.getElementById('CC_calculateur');
  if(!mount){console.error('[CC] #CC_calculateur introuvable.');return;}
  if(mount.getAttribute('data-cc-init')==='1')return;
  mount.setAttribute('data-cc-init','1');

  var pre1=document.createElement('link');pre1.rel='preconnect';pre1.href='https://fonts.googleapis.com';document.head.appendChild(pre1);
  var pre2=document.createElement('link');pre2.rel='preconnect';pre2.href='https://fonts.gstatic.com';pre2.crossOrigin='';document.head.appendChild(pre2);
  var font=document.createElement('link');font.rel='stylesheet';font.href='https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800';document.head.appendChild(font);

  try{var st=document.createElement('style');st.textContent=CC_decodeB64(CC_CSS_B64);document.head.appendChild(st);}catch(e){console.error('[CC] CSS inject fail',e);}
  try{mount.innerHTML=CC_decodeB64(CC_HTML_B64);if(cb)cb();}catch(e){console.error('[CC] HTML inject fail',e);mount.innerHTML='<p style="font-family:sans-serif;color:#c0392b;padding:16px">Erreur d\'affichage du calculateur.</p>';}
}

// ─────────────────────────────────────────────────────────
//  TABLE PROFIB CELL — données fabricant
//  Chaque zone: tableau [R, baseDens(lb/pi³), ep_pouces]
//  baseDens = densité à cette épaisseur à la densité de référence
// ─────────────────────────────────────────────────────────
var CC_TABLE = {
  // Grenier (soufflage horizontal, densité base 1.52 lb/pi³)
  grenier: [
    {r:12, ep:3.5,  baseDens:1.52},
    {r:19, ep:5.5,  baseDens:1.52},
    {r:22, ep:6.25, baseDens:1.52},
    {r:30, ep:8.5,  baseDens:1.52},
    {r:38, ep:10.75,baseDens:1.52},
    {r:44, ep:12.5, baseDens:1.52},
    {r:49, ep:14.0, baseDens:1.52},
    {r:60, ep:17.0, baseDens:1.52},
    {r:70, ep:19.75,baseDens:1.52},
    {r:80, ep:22.5, baseDens:1.52},
    {r:100,ep:28.25,baseDens:1.52},
    {r:120,ep:34.0, baseDens:1.52}
  ],
  // Plafond-plancher (dense-pack horizontal, densité base 1.87 lb/pi³)
  plafonds: [
    {r:13,  ep:3.5,  baseDens:1.87},
    {r:19,  ep:5.5,  baseDens:1.87},
    {r:22,  ep:6.25, baseDens:1.87},
    {r:26,  ep:7.5,  baseDens:1.87},
    {r:30,  ep:8.5,  baseDens:1.87},
    {r:38,  ep:10.75,baseDens:1.87},
    {r:44,  ep:12.5, baseDens:1.87},
    {r:49,  ep:14.0, baseDens:1.87},
    {r:59,  ep:16.75,baseDens:1.87}
  ],
  // Murs (dense-pack vertical, densité base 3.5 lb/pi³ → on utilise dense-pack)
  murs: [
    {r:13,  ep:3.5,  baseDens:3.5},
    {r:19,  ep:5.5,  baseDens:3.5},
    {r:21,  ep:6.0,  baseDens:3.5},
    {r:24,  ep:7.0,  baseDens:3.5},
    {r:28,  ep:8.0,  baseDens:3.5},
    {r:35,  ep:10.0, baseDens:3.5},
    {r:42,  ep:12.0, baseDens:3.5},
    {r:49,  ep:14.0, baseDens:3.5},
    {r:59,  ep:16.75,baseDens:3.5}
  ]
};

// ── Interpolation linéaire R→épaisseur ou épaisseur→R ──
function CC_interpR2Ep(zone, r){
  var t=CC_TABLE[zone]||CC_TABLE.grenier;
  if(r<=t[0].r) return t[0].ep;
  if(r>=t[t.length-1].r) return t[t.length-1].ep;
  for(var i=0;i<t.length-1;i++){
    if(r>=t[i].r&&r<=t[i+1].r){
      var frac=(r-t[i].r)/(t[i+1].r-t[i].r);
      return t[i].ep+frac*(t[i+1].ep-t[i].ep);
    }
  }
  return t[0].ep;
}
function CC_interpEp2R(zone, ep){
  var t=CC_TABLE[zone]||CC_TABLE.grenier;
  if(ep<=t[0].ep) return t[0].r;
  if(ep>=t[t.length-1].ep) return t[t.length-1].r;
  for(var i=0;i<t.length-1;i++){
    if(ep>=t[i].ep&&ep<=t[i+1].ep){
      var frac=(ep-t[i].ep)/(t[i+1].ep-t[i].ep);
      return t[i].r+frac*(t[i+1].r-t[i].r);
    }
  }
  return t[0].r;
}
// Sacs pour une surface donnée
// surfPi2: pi², ep: pouces, dens: lb/pi³
// Sac PROFIB CELL = 12.7 kg = 28 lbs
var CC_SAC_LBS = 28.0;
function CC_sacsForSurf(zone, surfPi2, ep, dens){
  if(!surfPi2||!ep||!dens) return 0;
  var baseDens=(CC_TABLE[zone]||CC_TABLE.grenier)[0].baseDens;
  // volume pi³ = surf * ep/12
  var volPi3=surfPi2*(ep/12);
  // masse lbs = vol * baseDens, ajustée selon densité réelle
  var massLbs=volPi3*dens;
  return massLbs/CC_SAC_LBS;
}
// R d'un mur selon épaisseur et densité (dense-pack)
function CC_rForMurEpDens(ep, dens){
  // On utilise la table murs avec ajustement densité
  var r0=CC_interpEp2R('murs',ep);
  // Correction linéaire ±densité vs base 3.5
  var adj=1+(dens-3.5)*0.04; // ~4% par unité de densité
  return r0*adj;
}

// ─────────────────────────────────────────────────────────
//  UTILITAIRES
// ─────────────────────────────────────────────────────────
var CC_SAVE_KEY='gp_cc_profibcell_v1';
var CC_ZOOM_KEY='gp_cc_profibcell_zoom_v1';
var CC_unitSystem='imp';
var CC_sections=[{id:'s1',name:'Section 1'}];
var CC_zoomLevels=[0.8,0.875,0.95,1,1.075,1.15,1.25,1.4];
var CC_zoomIdx=3;

function CC_gid(id){return document.getElementById(id);}
function CC_pf(s){if(typeof s!=='string')s=String(s||'');s=s.trim().replace(',','.');var n=parseFloat(s);return isNaN(n)?0:n;}
function CC_fmt(n,dec){if(isNaN(n)||n===null)return '—';if(dec===undefined)dec=1;return Number(n.toFixed(dec)).toLocaleString('fr-CA',{maximumFractionDigits:dec});}
function CC_fmtInt(n){if(isNaN(n)||n===null)return '—';return Math.ceil(n).toString();}

// Conversion mm ↔ pouces
var CC_IN2MM=25.4;
// Facteurs de conversion vers le métrique (affichage uniquement ; le calcul reste impérial)
var CC_PI2_M2=0.09290304;   // pi² → m²
var CC_PI_M=0.3048;         // pi → m
var CC_R_TO_RSI=5.678263;   // R (impérial) → RSI : RSI = R / 5.678263
// Affichage d'une surface selon l'unité courante (valeur seule, l'unité est dans l'en-tête)
function CC_surfU(){return CC_unitSystem==='mm'?'m\u00b2':'pi\u00b2';}
function CC_dispSurf(pi2){return CC_unitSystem==='mm'?CC_fmt(pi2*CC_PI2_M2,2):CC_fmt(pi2,1);}
// Affichage d'une épaisseur (po → mm)
function CC_dispEp(po){return CC_unitSystem==='mm'?CC_fmt(po*CC_IN2MM,0):CC_fmt(po,1);}
// Affichage d'une valeur R (R → RSI)
function CC_dispR(r){return CC_unitSystem==='mm'?'RSI-'+CC_fmt(r/CC_R_TO_RSI,2):'R-'+Math.round(r);}
// Affichage d'une longueur en pieds (pi → m)
function CC_dispLenFt(ft){return CC_unitSystem==='mm'?CC_fmt(ft*CC_PI_M,2):CC_fmt(ft,2);}
// ── Champs scalaires éditables : affichage en unité courante, stockage canonique impérial ──
var CC_LB_KGM3=16.018463;   // lb/pi³ → kg/m³
function CC_epDispV(po){return CC_unitSystem==='mm'?CC_fmt(po*CC_IN2MM,0):(po===Math.round(po)?String(po):CC_fmt(po,2));}
function CC_epCanonV(v){var n=CC_pf(v);return CC_unitSystem==='mm'?n/CC_IN2MM:n;}
function CC_densDispV(lb){return CC_unitSystem==='mm'?CC_fmt(lb*CC_LB_KGM3,1):(lb===Math.round(lb)?String(lb):CC_fmt(lb,2));}
function CC_densCanonV(v){var n=CC_pf(v);return CC_unitSystem==='mm'?n/CC_LB_KGM3:n;}
function CC_rDispV(r){return CC_unitSystem==='mm'?CC_fmt(r/CC_R_TO_RSI,2):String(Math.round(r));}
function CC_rCanonV(v){var n=CC_pf(v);return CC_unitSystem==='mm'?n*CC_R_TO_RSI:n;}
// Lecture canonique (impérial) d'un champ scalaire, quelle que soit l'unité affichée
function CC_fldEp(id){var e=CC_gid(id);return e?CC_epCanonV(e.value):0;}
function CC_fldDens(id){var e=CC_gid(id);return e?CC_densCanonV(e.value):0;}
function CC_fldR(id){var e=CC_gid(id);return e?CC_rCanonV(e.value):0;}
// Masse par sac PROFIB CELL — valeur CANONIQUE en kg (le champ affiche kg ou lbs).
var CC_SAC_KG=12.7;
var CC_KG_TO_LBS=2.20462;
// Affiche la masse par sac dans l'unité courante du système (kg en mm, lbs en imp)
// et ajuste l'étiquette « kg / sac » ↔ « lbs / sac ».
function CC_renderSackField(){
  var fld=CC_gid('CC_pCellKg');
  var lbl=CC_gid('CC_pCellKgLabel');
  var isImp=CC_unitSystem!=='mm';
  if(fld)fld.value=isImp?Number((CC_SAC_KG*CC_KG_TO_LBS).toFixed(1)):Number(CC_SAC_KG.toFixed(1));
  if(lbl)lbl.textContent=isImp?'lbs / sac':'kg / sac';
}
function CC_inToMm(po){return po*CC_IN2MM;}
function CC_mmToIn(mm){return mm/CC_IN2MM;}
// Lire dimension imp (pi+po) → pouces
function CC_readImpPi(piId,poId){
  var pi=CC_pf(CC_gid(piId)?CC_gid(piId).value:0);
  var po=CC_pf(CC_gid(poId)?CC_gid(poId).value:0);
  return pi*12+po;
}
// Écrire pouces → champs pi+po
function CC_writeImpPi(piId,poId,po){
  var pi=Math.floor(po/12);
  var poR=po-pi*12;
  if(CC_gid(piId))CC_gid(piId).value=pi?String(pi):'';
  if(CC_gid(poId))CC_gid(poId).value=CC_fmtFrac(poR);
}
function CC_fmtFrac(po){
  if(!po)return '';
  var eighths=Math.round(po*8);
  if(eighths%8===0)return String(eighths/8);
  if(eighths%4===0)return (eighths/4)+'/4';
  if(eighths%2===0)return (eighths/2)+'/8';
  return po.toFixed(3);
}
// Lire une dim selon unité système courante
function CC_readDim(piId,poId,mmId){
  if(CC_unitSystem==='mm'){
    var mm=CC_pf(CC_gid(mmId)?CC_gid(mmId).value:0);
    return CC_mmToIn(mm);
  }
  return CC_readImpPi(piId,poId);
}
// Dimension en pi²
function CC_surfFromDims(l_po, w_po){return (l_po/12)*(w_po/12);}
// Surface d'une rangée : priorité aux dimensions SI les deux sont saisies (> 0),
// sinon au pi² manuel (row.surf). Permet « pi² OU dimensions » sans qu'une
// dimension partielle (une seule des deux) ne remette la surface à zéro.
// kind : 'lw' (longueur×largeur) ou 'lh' (longueur×hauteur, murs).
function CC_rowSurf(row,kind){
  var a,b;
  if(CC_unitSystem==='mm'){
    a=CC_mmToIn(CC_pf(row.l_mm));
    b=CC_mmToIn(CC_pf(kind==='lh'?row.h_mm:row.w_mm));
  } else {
    a=(CC_pf(row.l_pi)||0)*12+(CC_pf(row.l_po)||0);
    b=(kind==='lh')
      ?(CC_pf(row.h_pi)||0)*12+(CC_pf(row.h_po)||0)
      :(CC_pf(row.w_pi)||0)*12+(CC_pf(row.w_po)||0);
  }
  if(a>0&&b>0)return {surf:CC_surfFromDims(a,b),fromDims:true};
  var man=CC_pf(row.surf);
  if(man>0)return {surf:man,fromDims:false};
  return {surf:0,fromDims:false};
}

// ─────────────────────────────────────────────────────────
//  NAVIGATION
//  Le collage du menu et du résumé est géré par position:sticky (CSS),
//  identique au calculateur de béton de chanvre. Pas de pilotage JS.
// ─────────────────────────────────────────────────────────
var CC_navSections=['sec-fichier','sec-projet','sec-config','sec-grenier','sec-plafond','sec-murs','sec-pignons','sec-ouvertures','sec-buffer','sec-materiaux'];
function CC_navTo(id){
  var el=document.getElementById(id);if(!el)return;
  var nav=document.querySelector('.inputs-nav');
  var navH=nav?nav.getBoundingClientRect().height:120;
  var offset=navH+100;
  var top=el.getBoundingClientRect().top+window.scrollY-offset;
  window.scrollTo({top:top,behavior:'smooth'});
}
function CC_onScroll(){
  var nav=document.querySelector('.inputs-nav');
  var offset=(nav?nav.getBoundingClientRect().height:120)+150;
  var active=CC_navSections[0];
  for(var i=0;i<CC_navSections.length;i++){
    var el=document.getElementById(CC_navSections[i]);
    if(!el)continue;
    if(el.getBoundingClientRect().top<=offset)active=CC_navSections[i];
  }
  document.querySelectorAll('.nav-btn[data-target]').forEach(function(btn){
    btn.classList.toggle('active',btn.dataset.target===active);
  });
}

// ─────────────────────────────────────────────────────────
//  ZOOM
// ─────────────────────────────────────────────────────────
function CC_applyZoom(){
  var z=CC_zoomLevels[CC_zoomIdx];
  document.documentElement.style.fontSize=(z*100)+'%';
  var lbl=CC_gid('CC_zoomLabel');
  if(lbl)lbl.textContent=Math.round(z*100)+'%';
}
function CC_zoomStep(d){
  CC_zoomIdx=Math.max(0,Math.min(CC_zoomLevels.length-1,CC_zoomIdx+d));
  CC_applyZoom();
  try{localStorage.setItem(CC_ZOOM_KEY,String(CC_zoomIdx));}catch(e){}
}

// ─────────────────────────────────────────────────────────
//  UNITÉS
// ─────────────────────────────────────────────────────────
// Conversion des dimensions stockées lors d'un changement d'unité.
// Les longueurs/largeurs/hauteurs sont saisies en pi+po OU en mm ; on convertit
// la représentation source vers la cible pour que les valeurs suivent la bascule
// (équivalent du stockage canonique du calculateur de béton de chanvre).
function CC_convertAllDims(from,to){
  if(from===to)return;
  var groups={
    grenier:[['l_pi','l_po','l_mm'],['w_pi','w_po','w_mm']],
    plafonds:[['l_pi','l_po','l_mm'],['w_pi','w_po','w_mm']],
    murs:[['l_pi','l_po','l_mm'],['h_pi','h_po','h_mm']],
    pig:[['l1_pi','l1_po','l1_mm'],['l2_pi','l2_po','l2_mm']],
    ouv:[['l_pi','l_po','l_mm'],['h_pi','h_po','h_mm']]
  };
  Object.keys(groups).forEach(function(z){
    (CC_rows[z]||[]).forEach(function(row){
      groups[z].forEach(function(g){
        var piK=g[0],poK=g[1],mmK=g[2];
        if(to==='mm'){
          var inches=(CC_pf(row[piK])||0)*12+(CC_pf(row[poK])||0);
          row[mmK]=inches>0?String(Math.round(inches*CC_IN2MM*10)/10):'';
        } else {
          var mm=CC_pf(row[mmK])||0;
          if(mm>0){
            var inches=mm/CC_IN2MM;
            var pi=Math.floor(inches/12);
            var po=Math.round((inches-pi*12)*100)/100;
            row[piK]=String(pi);row[poK]=po?String(po):'';
          } else { row[piK]='';row[poK]=''; }
        }
      });
    });
  });
}

// Conversion de l'AFFICHAGE des champs scalaires (épaisseur, densité, R) au
// changement d'unité. Les sliders restent en valeur impériale (inchangés) ; seuls
// les champs texte changent d'affichage. Le canonique reste impérial.
function CC_convertScalarFields(from,to){
  if(from===to)return;
  var IN=25.4,LB=16.018463,RR=5.678263;
  function ep(v){var n=CC_pf(v);if(!n)return v;var c=from==='mm'?n/IN:n;return to==='mm'?String(Math.round(c*IN)):(c===Math.round(c)?String(c):CC_fmt(c,2));}
  function dn(v){var n=CC_pf(v);if(!n)return v;var c=from==='mm'?n/LB:n;return to==='mm'?CC_fmt(c*LB,1):(c===Math.round(c)?String(c):CC_fmt(c,2));}
  function rn(v){var n=CC_pf(v);if(!n)return v;var c=from==='mm'?n*RR:n;return to==='mm'?CC_fmt(c/RR,2):String(Math.round(c));}
  ['CC_grenierEp','CC_mursEp','CC_pigEp','CC_plafondHt','CC_cfgGrenierEp','CC_cfgMursEp','CC_cfgPlafondsEp'].forEach(function(id){var e=CC_gid(id);if(e&&e.value!=='')e.value=ep(e.value);});
  ['CC_grenierDens','CC_mursDens','CC_pigDens','CC_plafondDens','CC_cfgGrenierDens','CC_cfgMursDens','CC_cfgPlafondsDens'].forEach(function(id){var e=CC_gid(id);if(e&&e.value!=='')e.value=dn(e.value);});
  ['CC_grenierR','CC_cfgGrenierR','CC_cfgMursR','CC_cfgPlafondsR'].forEach(function(id){var e=CC_gid(id);if(e&&e.value!=='')e.value=rn(e.value);});
  // R calculés (readonly) : mursRHdr, plafondR — reformatés (préfixe R-/RSI-)
  ['CC_mursRHdr','CC_pigRHdr','CC_plafondR'].forEach(function(id){var e=CC_gid(id);if(!e)return;var raw=CC_pf(String(e.value).replace(/RSI-|R-/,''));if(!raw)return;var c=from==='mm'?raw*RR:raw;e.value=to==='mm'?'RSI-'+CC_fmt(c/RR,2):'R-'+Math.round(c);});
}
// Met à jour les libellés d'unité des en-têtes de zone et de la config.
function CC_updateScalarLabels(){
  var isImp=CC_unitSystem!=='mm';
  var epU=isImp?'(po)':'(mm)', dnU=isImp?'(lbs/pi\u00b3)':'(kg/m\u00b3)';
  [['CC_grenierEpHdrUnit',epU],['CC_mursEpUnit',epU],['CC_pigEpUnit',epU],['CC_plafondHtHdrUnit',epU]].forEach(function(p){var e=CC_gid(p[0]);if(e)e.textContent=p[1];});
  document.querySelectorAll('.dens-unit').forEach(function(e){e.textContent=dnU;});
  document.querySelectorAll('.ep-unit').forEach(function(e){e.textContent=epU;});
  document.querySelectorAll('.r-unit').forEach(function(e){e.textContent=isImp?'(R)':'(RSI)';});
}

function CC_setUnitSystem(sys,btn,skipConvert){
  var old=CC_unitSystem;
  CC_unitSystem=sys;
  // Convertit dimensions + champs scalaires vers la nouvelle unité (sauf au chargement).
  if(!skipConvert&&old&&old!==sys){CC_convertAllDims(old,sys);CC_convertScalarFields(old,sys);}
  // Bascule nav seg — l'état actif suit l'unité (robuste même si btn absent, ex. au chargement)
  var seg=CC_gid('CC_unitSeg');
  if(seg)seg.querySelectorAll('button').forEach(function(b){
    var bUnit=/mm/i.test(b.textContent)?'mm':'imp';
    b.classList.toggle('active',bUnit===sys);
  });
  // Met à jour les tbody data-dimunit
  document.querySelectorAll('tbody[id^="CC_tbody_"]').forEach(function(tb){
    tb.setAttribute('data-dimunit',sys);
  });
  // Labels unités — toutes les zones et toutes les colonnes concernées.
  var isImp=sys==='imp';
  var L=isImp?'(pi \u00b7 po)':'(mm)';   // longueurs
  var A=isImp?'(pi\u00b2)':'(m\u00b2)';   // surfaces
  var T=isImp?'(po)':'(mm)';             // épaisseurs
  var R=isImp?'(R)':'(RSI)';             // valeur R
  var P=isImp?'(pi)':'(m)';              // périmètre / segment
  var thu={
    grenier:{l:L,w:L,surf:A,ep:T,r:R},
    plafonds:{l:L,w:L,surf:A,ep:T,r:R},
    murs:{l:L,h:L,surf:A,ep:T,r:R},
    pig:{l1:L,l2:L,surf:A,seg:P,ep:T},
    ouv:{l:L,h:L,jeu:T,surf:A,perim:P}
  };
  Object.keys(thu).forEach(function(z){
    Object.keys(thu[z]).forEach(function(k){
      var el=document.getElementById('CC_thu_'+z+'_'+k);
      if(el)el.textContent=thu[z][k];
    });
  });
  var hautEl=CC_gid('CC_hauteurGlobalUnit');
  if(hautEl)hautEl.textContent=isImp?'(pi \u00b7 po)':'(mm)';
  // Champs hauteur global
  var hImp=CC_gid('CC_hauteurGlobalImp'),hMm=CC_gid('CC_hauteurGlobalMm');
  if(hImp)hImp.style.display=isImp?'inline-flex':'none';
  if(hMm)hMm.style.display=isImp?'none':'flex';
  // (La config murs est désormais en po uniquement — pas de bascule pi/po/mm.)

  CC_renderSackField(); // le champ « kg/sac » ↔ « lbs/sac » suit le système d'unités
  CC_updateScalarLabels(); // libellés (po)/(mm), (lbs/pi³)/(kg/m³)
  if(typeof CC_renderAllTables==='function')CC_renderAllTables(); // affiche les dims converties
  CC_recalc();
}

// ─────────────────────────────────────────────────────────
//  SECTIONS
// ─────────────────────────────────────────────────────────
function CC_renderSectionsBar(){
  var bar=CC_gid('CC_sectionsBar');
  if(!bar)return;
  bar.innerHTML='';
  CC_sections.forEach(function(sec){
    var chip=document.createElement('div');
    chip.className='sec-chip';
    chip.innerHTML='<input class="sec-chip-name" type="text" value="'+sec.name+'" onchange="CC_renameSection(\''+sec.id+'\',this.value)">'
      +'<button class="sec-chip-del" onclick="CC_delSection(\''+sec.id+'\')" title="Supprimer">&#215;</button>';
    bar.appendChild(chip);
  });
  var addBtn=document.createElement('button');
  addBtn.className='sec-add-btn';
  addBtn.textContent='+ Ajouter une section';
  addBtn.onclick=CC_addSection;
  bar.appendChild(addBtn);
}
function CC_addSection(){
  var n=CC_sections.length+1;
  CC_sections.push({id:'s'+Date.now(),name:'Section '+n});
  CC_renderSectionsBar();
  CC_renderAllTables();
}
function CC_renameSection(id,name){
  var sec=CC_sections.find(function(s){return s.id===id;});
  if(sec)sec.name=name;
  CC_renderAllTables();
}
function CC_delSection(id){
  if(CC_sections.length<=1)return;
  CC_sections=CC_sections.filter(function(s){return s.id!==id;});
  // Réassigner les rangées orphelines à la première section
  var firstId=CC_sections[0].id;
  ['grenier','plafonds','murs','pig','ouv'].forEach(function(z){
    (CC_rows[z]||[]).forEach(function(r){if(r.secId===id)r.secId=firstId;});
  });
  CC_renderSectionsBar();
  CC_renderAllTables();
}

// ─────────────────────────────────────────────────────────
//  DONNÉES RANGÉES
// ─────────────────────────────────────────────────────────
var CC_rows={grenier:[],plafonds:[],murs:[],pig:[],ouv:[]};
var CC_rowCounter=0;
function CC_newRowId(){return 'r'+(++CC_rowCounter);}

function CC_defaultRow(zone){
  var r={id:CC_newRowId(),secId:CC_sections[0].id,label:'',qty:1};
  if(zone==='grenier'){
    r.l_pi='';r.l_po='';r.l_mm='';
    r.w_pi='';r.w_po='';r.w_mm='';
    r.surf=''; // valeur directe
    r.rVal=CC_cfgVal('grenier','r');
    r.ep=CC_cfgVal('grenier','ep');
    r.dens=CC_cfgVal('grenier','dens');
  } else if(zone==='plafonds'){
    r.l_pi='';r.l_po='';r.l_mm='';
    r.w_pi='';r.w_po='';r.w_mm='';
    r.surf='';
    r.ht=CC_cfgVal('plafonds','ep');
    r.dens=CC_cfgVal('plafonds','dens');
  } else if(zone==='murs'){
    r.l_pi='';r.l_po='';r.l_mm='';
    r.h_pi='8';r.h_po='';r.h_mm='';
    r.surf='';
    r.ep=CC_cfgVal('murs','ep');
    r.dens=CC_cfgVal('murs','dens');
  } else if(zone==='pig'){
    r.type='mono';
    r.l1_pi='';r.l1_po='';r.l1_mm='';
    r.pente1=6;
    r.l2_pi='';r.l2_po='';r.l2_mm='';
    r.pente2=6;
    r.ep=CC_cfgVal('murs','ep');
    r.dens=CC_cfgVal('murs','dens');
  } else if(zone==='ouv'){
    r.code='';r.empl='';
    r.l_pi='';r.l_po='';r.l_mm='';
    r.h_pi='';r.h_po='';r.h_mm='';
    r.jeu=0.5;
    r.zone='murs'; // zone associée pour le calcul des sacs
  }
  return r;
}

function CC_addRow(zone,secId){
  var r=CC_defaultRow(zone);
  if(secId&&CC_sections.some(function(s){return s.id===secId;}))r.secId=secId;
  CC_rows[zone].push(r);
  CC_renderTable(zone);
  CC_recalc();
  // Place le focus sur le premier champ de la nouvelle rangée (label, ou code pour ouv).
  var firstId=zone==='ouv'?('CC_code_'+r.id):null;
  var el=firstId?CC_gid(firstId):null;
  if(!el){
    var tr=document.querySelector('#CC_tbody_'+zone+' tr[data-rowid="'+r.id+'"]');
    if(tr)el=tr.querySelector('input.id-field,input.tbl-input');
  }
  if(el){el.focus();if(el.select)el.select();}
  return r.id;
}

// Tab depuis le dernier champ saisissable d'une rangée : focus la rangée suivante
// de la même section, ou crée une nouvelle ligne dans cette section (façon béton de chanvre).
function CC_tabNext(zone,rowId){
  var rows=CC_rows[zone]||[];
  var row=rows.find(function(r){return r.id===rowId;});
  if(!row)return;
  var grp=rows.filter(function(r){return r.secId===row.secId;});
  var gidx=grp.findIndex(function(r){return r.id===rowId;});
  if(gidx<grp.length-1){
    // Focus le premier champ de la rangée suivante (même section).
    var nextId=grp[gidx+1].id;
    var tr=document.querySelector('#CC_tbody_'+zone+' tr[data-rowid="'+nextId+'"]');
    var el=tr?tr.querySelector('input.id-field,input.tbl-input'):null;
    if(el){el.focus();if(el.select)el.select();}
  } else {
    CC_addRow(zone,row.secId);
  }
}

// ─────────────────────────────────────────────────────────
//  RENDU DES TABLEAUX
// ─────────────────────────────────────────────────────────
function CC_renderAllTables(){
  ['grenier','plafonds','murs','pig','ouv'].forEach(CC_renderTable);
  CC_recalc();
}

function CC_renderTable(zone){
  var tbody=CC_gid('CC_tbody_'+zone);
  if(!tbody)return;
  tbody.setAttribute('data-dimunit',CC_unitSystem);
  tbody.innerHTML='';

  var rows=CC_rows[zone]||[];
  var hasSecs=CC_sections.length>1;

  if(hasSecs){
    CC_sections.forEach(function(sec){
      var secRows=rows.filter(function(r){return r.secId===sec.id;});
      // Header section
      var headTr=document.createElement('tr');
      headTr.className='sec-group-head';
      headTr.setAttribute('data-secid',sec.id);
      var ncols=zone==='grenier'||zone==='plafonds'?9:(zone==='murs'?9:(zone==='pig'?12:10));
      headTr.innerHTML='<td colspan="'+ncols+'"><div class="sec-group-head-inner">'
        +'<span class="sec-group-name">'+sec.name+'</span>'
        +'<button class="sec-group-add" onclick="CC_addRowToSection(\''+zone+'\',\''+sec.id+'\')">+ Ajouter</button>'
        +'</div></td>';
      tbody.appendChild(headTr);
      // Rangées (zébrage par section)
      secRows.forEach(function(row,i){
        var tr=CC_makeRowTr(zone,row);
        if(i%2===1)tr.classList.add('row-alt');
        tbody.appendChild(tr);
      });
      // Sous-total section
      var subTr=document.createElement('tr');
      subTr.className='sec-group-sub';
      subTr.setAttribute('data-sec-sub',sec.id);
      subTr.innerHTML=CC_makeSecSubTd(zone,sec.id,rows);
      tbody.appendChild(subTr);
    });
  } else {
    rows.forEach(function(row,i){
      var tr=CC_makeRowTr(zone,row);
      if(i%2===1)tr.classList.add('row-alt');
      tbody.appendChild(tr);
    });
  }
  CC_initDragDrop(zone);
  if(typeof CC_updateStickyHeads==='function')CC_updateStickyHeads();
}

function CC_addRowToSection(zone,secId){
  var r=CC_defaultRow(zone);
  r.secId=secId;
  CC_rows[zone].push(r);
  CC_renderTable(zone);
  CC_recalc();
}

function CC_makeRowTr(zone,row){
  var tr=document.createElement('tr');
  tr.setAttribute('data-rowid',row.id);
  tr.setAttribute('draggable','true');

  // Le changement de section se fait UNIQUEMENT par glisser-déposer (grip),
  // comme dans le calculateur de béton de chanvre. Pas de menu déroulant en doublon.
  var secSel='';

  var dupBtn='<button class="btn-dup-row" onclick="CC_dupRow(\''+zone+'\',\''+row.id+'\')" title="Dupliquer">'
    +'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>'
    +'</button>';
  var delBtn='<button class="btn-remove-row" onclick="CC_removeRow(\''+zone+'\',\''+row.id+'\')" title="Supprimer">&#215;</button>';
  var grip='<span class="row-grip" title="Glisser pour d&eacute;placer">&#8942;&#8942;</span>';

  if(zone==='grenier'||zone==='plafonds'){
    tr.innerHTML=CC_makeAreaRowHtml(zone,row,secSel,grip,dupBtn,delBtn);
  } else if(zone==='murs'){
    tr.innerHTML=CC_makeMurRowHtml(row,secSel,grip,dupBtn,delBtn);
  } else if(zone==='pig'){
    tr.innerHTML=CC_makePigRowHtml(row,secSel,grip,dupBtn,delBtn);
  } else if(zone==='ouv'){
    tr.innerHTML=CC_makeOuvRowHtml(row,secSel,grip,dupBtn,delBtn);
  }
  return tr;
}

function CC_dimImpHtml(piId,poId,piVal,poVal,onchange){
  return '<span class="dim-imp">'
    +'<span class="dim-pair"><input type="text" id="'+piId+'" class="tbl-input dim-in" size="3" value="'+( piVal||'')+'" oninput="'+onchange+'"> <span class="dim-suf">pi</span></span>'
    +'<span class="dim-pair"><input type="text" id="'+poId+'" class="tbl-input dim-in" size="3" value="'+(poVal||'')+'" oninput="'+onchange+'"> <span class="dim-suf">po</span></span>'
    +'</span>';
}
function CC_dimMmHtml(mmId,mmVal,onchange){
  return '<span class="dim-mm"><input type="text" id="'+mmId+'" class="tbl-input dim-in" size="5" value="'+(mmVal||'')+'" oninput="'+onchange+'"> <span class="dim-suf">mm</span></span>';
}

function CC_makeAreaRowHtml(zone,row,secSel,grip,dupBtn,delBtn){
  var rid=row.id;
  var oc="CC_onRowInput('"+zone+"','"+rid+"')";
  var labelPart='<div class="id-cell">'+grip+dupBtn+'<input type="text" class="tbl-input id-field" value="'+(row.label||'')+'" placeholder="Nom…" oninput="CC_setRowProp(\''+zone+'\',\''+rid+'\',\'label\',this.value)"></div>';
  var qtyPart='<input type="text" class="tbl-input" value="'+(row.qty||1)+'" oninput="CC_setRowProp(\''+zone+'\',\''+rid+'\',\'qty\',this.value);'+oc+'" style="width:44px;text-align:center">';
  var lPart=CC_dimImpHtml('CC_l_pi_'+rid,'CC_l_po_'+rid,row.l_pi,row.l_po,oc)+CC_dimMmHtml('CC_l_mm_'+rid,row.l_mm,oc);
  var wPart=CC_dimImpHtml('CC_w_pi_'+rid,'CC_w_po_'+rid,row.w_pi,row.w_po,oc)+CC_dimMmHtml('CC_w_mm_'+rid,row.w_mm,oc);
  // Surf directe
  var surfPart='<input type="text" class="tbl-input" id="CC_surf_'+rid+'" value="'+(row.surf||'')+'" placeholder="auto" oninput="CC_onSurfInput(\''+zone+'\',\''+rid+'\',this.value)" style="width:70px;text-align:right">';
  var rPart='<input type="text" class="tbl-input computed" id="CC_r_'+rid+'" value="" readonly tabindex="-1" style="width:50px">';
  var epPart='<input type="text" class="tbl-input computed" id="CC_ep_'+rid+'" value="" readonly tabindex="-1" style="width:50px">';
  var sacsPart='<span class="tbl-input computed" id="CC_sacs_'+rid+'">—</span>';
  return '<td>'+labelPart+'</td>'
    +'<td>'+qtyPart+'</td>'
    +'<td>'+lPart+'</td>'
    +'<td>'+wPart+'</td>'
    +'<td class="col-surf">'+surfPart+'</td>'
    +'<td class="col-r">'+rPart+'</td>'
    +'<td class="col-ep">'+epPart+'</td>'
    +'<td class="col-sacs">'+sacsPart+'</td>'
    +'<td><div class="row-actions">'+delBtn+'</div></td>';
}

