  var qtyPart='<input type="text" class="tbl-input" value="'+(row.qty||1)+'" oninput="CC_setRowProp(\'murs\',\''+rid+'\',\'qty\',this.value);'+oc+'" style="width:44px;text-align:center">';
  var lPart=CC_dimImpHtml('CC_l_pi_'+rid,'CC_l_po_'+rid,row.l_pi,row.l_po,oc)+CC_dimMmHtml('CC_l_mm_'+rid,row.l_mm,oc);
  var hPart=CC_dimImpHtml('CC_h_pi_'+rid,'CC_h_po_'+rid,row.h_pi,row.h_po,oc)+CC_dimMmHtml('CC_h_mm_'+rid,row.h_mm,oc);
  var surfPart='<input type="text" class="tbl-input" id="CC_surf_'+rid+'" value="'+(row.surf||'')+'" placeholder="auto" oninput="CC_onSurfInput(\'murs\',\''+rid+'\',this.value)" style="width:70px;text-align:right">';
  var rPart='<span class="tbl-input computed" id="CC_r_'+rid+'">—</span>';
